insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) select id,kind,title,course_id,payload,published,restaurant_id,department from jsonb_populate_record(null::public.academy_content,$doc${"id":"rvb-assortment-test-alcohol","kind":"test","title":"РВБ · Крепкий алкоголь и аперитивы","course_id":"rvb-bar-assortment","published":true,"restaurant_id":"minsk","department":"Бар","payload":{"id":"rvb-assortment-test-alcohol","title":"РВБ · Крепкий алкоголь и аперитивы","priority":"attestation","questions":[{"id":"rvb-menu-alcohol-1","text":"Какой напиток описан в меню РВБ так: «Аперитив на винной основе с ярким апельсиновым профилем.»?","type":"single","options":["Martini Fiero","Martini Bianco","Martini Rosso","Martini Extra Dry"]},{"id":"rvb-menu-alcohol-2","text":"Какой напиток описан в меню РВБ так: «Белый вермут с лёгкой сладостью, ванильными и травяными нотами.»?","type":"single","options":["Martini Fiero","Martini Rosso","Martini Extra Dry","Martini Bianco"]},{"id":"rvb-menu-alcohol-3","text":"Какой напиток описан в меню РВБ так: «Сладкий вермут с горько-сладким травяным профилем.»?","type":"single","options":["Martini Bianco","Martini Extra Dry","Martini Rosso","Martini Fiero"]},{"id":"rvb-menu-alcohol-4","text":"Какой напиток описан в меню РВБ так: «Сухой вермут в линейке MARTINI. Отличается по стилю от сладких Bianco и Rosso.»?","type":"single","options":["Martini Rosso","Martini Extra Dry","Martini Fiero","Martini Bianco"]},{"id":"rvb-menu-alcohol-5","text":"Какой напиток описан в меню РВБ так: «Фруктовый коньяк с нотами яблока, груши и весенних цветов. В послевкусии — свежий дуб.»?","type":"single","options":["Courvoisier VS","Martini Fiero","Martini Bianco","Martini Rosso"]},{"id":"rvb-menu-alcohol-6","text":"Какой напиток описан в меню РВБ так: «Французский коньяк категории VSOP. Отдельная ступень в линейке Martell между VS и XO.»?","type":"single","options":["Martini Fiero","Martini Bianco","Martini Rosso","M