-- RVB bar learning content; no permissions or existing progress are changed.
begin;
update public.academy_content set title='Добро пожаловать в команду — 90-е и Руки Вверх Бар', payload=payload||jsonb_build_object('title','Добро пожаловать в команду — 90-е и Руки Вверх Бар','shortTitle','Добро пожаловать в команду','coverLabel','Знакомство с командой') where id='welcome-90' and kind='course';
update public.academy_content set title='Правила сотрудника',payload=payload||jsonb_build_object('title','Правила сотрудника','shortTitle','Правила сотрудника','coverLabel','Правила команды') where id='guru-43403' and kind='course';
commit;
select kind,count(*) from public.academy_content where id like 'rvb-bar-%' or id like 'rvb-assortment-test-%' or id like 'rvb-ttk-test-%' group by kind;
